var n=`0769-vitumbua`;var t=`world-0769`;var a=`TZ`;var o=`eastern-africa`;var r=8;var s=340;var l={en:`Vitumbua`,ua:`Вітумбуа`};var u={en:`Vitumbua is a Tanzania classic prepared with white rice, coconut milk, rice flour, instant yeast. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Вітумбуа, страва кухні країни Танзанія зі складниками: білий рис, кокосове молоко, рисове борошно, інстантні дріжджі. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Soak the rice until hydrated, drain well, then grind it to a fine batter for the coconut rice cakes.`,ua:`Замочіть рис до належного набухання, ретельно злийте воду й подрібніть на дрібне тісто для кокосових рисових оладок.`,t:[`rice-soaking`],m:240,i:[[`white-rice`,320,`g`],[`water`,500,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`coconut-milk`,300,`ml`],[`rice-flour`,120,`g`],[`white-granulated-sugar`,65,`g`],[`instant-yeast`,6,`g`],[`ground-cardamom`,3,`g`]]},{en:`Cover the batter loosely and leave in a suitable warm, clean place for about 60 minutes to become bubbly and lightly tangy; do not refrigerate during active fermentation.`,ua:`Нещільно накрийте тісто й залиште приблизно на 60 хвилин у чистому теплому місці до появи бульбашок і легкої кислинки; під час активного бродіння не ставте в холодильник.`,t:[`sourdough-fermentation`],m:60,i:[]},{en:`Cook spoonfuls of risen coconut-rice batter in lightly oiled small round molds, turning once so vitumbua are golden and set inside.`,ua:`Випікайте невеликі порції піднятого кокосово-рисового тіста у злегка змащених круглих формочках, перевернувши один раз до золотавості й готовності середини.`,t:[`pan-frying`],m:25,i:[[`sunflower-oil`,60,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`honey`,80,`g`]]}];var g={slug:n,id:t,country:`TZ`,region:o,servings:8,minutes:340,title:l,text:u,steps:d};export{a as country,g as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,u as text,l as title};